  chalk: () => part(130, 130, 140, 150, 26, 'red') + rr(180, 100, 40, 36, 6, 'url(#dark)') + path('M200 280 L200 335', 'none', 'stroke="#fff" stroke-width="3"') + rot(-35, 320, 250, part(300, 130, 22, 200, 4, 'yellow') + path('M300 130 L322 130 L311 100Z', '#e3b678') + circ(311, 100, 3, '#222')) + rot(-20, 80, 250, part(70, 150, 18, 180, 4, 'orange') + path('M70 150 L88 150 L79 125Z', '#f1d9b0') + circ(79, 125, 2.5, '#222')),
  marker: a => rot(-30, 200, 200, part(60, 175, 280, 50, 24, a, true) + part(300, 182, 70, 36, 14, 'white', true) + rr(305, 193, 60, 14, 3, '#fff', 'opacity=".0"') + path('M340 192 L388 200 L340 208Z', '#222') + rr(100, 185, 120, 30, 4, '#fff', 'opacity=".9"') + `<text x="160" y="206" font-family="Arial" font-weight="700" font-size="14" text-anchor="middle" fill="#111">MARKER</text>`),
  sensor: a => part(120, 70, 160, 260, 30, a) + rr(140, 100, 120, 80, 10, '#1f2a1d', 'stroke="#000"') + `<text x="200" y="152" font-family="monospace" font-weight="700" font-size="32" text-anchor="middle" fill="#9dff7a">12.4%</text>` + circ(200, 235, 26, 'url(#dark)') + circ(200, 235, 14, '#c9cfd6') + rr(170, 285, 60, 22, 8, 'url(#darkH)'),
