  drill: a => part(80, 130, 205, 85, 20, a, true) + part(150, 205, 70, 140, 20, 'dark') + part(150, 205, 70, 140, 20, 'dark') + rr(150, 330, 110, 28, 8, 'url(#darkH)') + part(285, 150, 40, 45, 6, 'steel', true) + rr(325, 165, 55, 14, 3, 'url(#steelH)') + rr(214, 185, 44, 15, 6, '#111') + circ(110, 172, 28, 'url(#dark)') + circ(110, 172, 12, '#aab1b9') + rr(95, 140, 150, 12, 4, '#fff', 'opacity=".2"') + path('M195 260 L195 300', 'none', 'stroke="#ffffff" stroke-opacity=".25" stroke-width="6" stroke-linecap="round"'),
  impact: a => part(80, 120, 170, 70, 20, a, true) + part(130, 185, 62, 130, 18, 'dark') + rr(120, 310, 100, 28, 8, 'url(#darkH)') + part(250, 140, 50, 34, 6, 'steel', true) + rr(300, 150, 60, 14, 3, 'url(#steelH)') + path('M308 150 L318 164 L330 150 L340 164 L350 150', 'none', 'stroke="#000" stroke-opacity=".4"') + circ(112, 155, 24, 'url(#dark)') + circ(112, 155, 9, '#aab1b9'),
  battery: a => part(110, 150, 180, 120, 14, 'dark', true) + part(130, 115, 140, 45, 10, a, true) + rr(140, 270, 120, 30, 6, 'url(#darkH)') + [0, 1, 2, 3, 4].map(i => rr(150 + i * 20, 128, 12, 20, 2, '#fff', 'opacity=".85"')).join('') + rr(170, 215, 60, 16, 4, a === 'red' ? '#d92d20' : '#ffd84a'),
