  accessory: () => rr(80, 190, 240, 20, 10, 'url(#steelH)', 'stroke="#000" stroke-opacity=".35"') + [110, 290].map(x => circ(x, 200, 22, 'url(#steel)', 'stroke="#000" stroke-opacity=".35"') + circ(x, 200, 7, '#6b727c')).join('') + path('M120 230 L120 330 M120 230 Q200 300 280 230', 'none', 'opacity="0"') + path('M130 218 L130 218 Q130 330 200 335 Q270 330 270 218', 'none', 'stroke="url(#steel)" stroke-width="12" opacity="0"') + path('M150 235 L250 235 L250 330 L150 330Z', 'url(#white)', 'opacity="0"'),
