  faucet: () => path('M110 330 L110 230 Q110 120 220 120 L290 120 L290 160 L230 160 Q160 160 160 230 L160 330Z', 'url(#steel)', 'stroke="#000" stroke-opacity=".35"') + part(240, 105, 70, 24, 10, 'steelH', true) + part(60, 330, 150, 18, 6, 'steelH', true) + rr(255, 130, 40, 14, 3, '#fff', 'opacity="0"') + gloss(110, 190, 50, 140, 12, 0.5),
