  stainer: a => bottle(a) + '',
  tray: a => path('M70 240 L330 240 L300 320 L100 320Z', `url(#${a})`, 'stroke="#000" stroke-opacity=".3"') + path('M80 230 Q200 200 320 230 L330 240 L70 240Z', '#e6e9ed', 'stroke="#9aa3ad"') + rr(250, 300, 90, 20, 6, '#000', 'opacity="0"'),
  cloth: a => path('M80 140 L320 120 L335 290 L95 310Z', `url(#${a})`, 'stroke="#000" stroke-opacity=".2"') + [...Array(8)].map((_, i) => line(95 + i * 28, 150 + i * 2, 100 + i * 29, 295 + i * 2, '#fff', 2, 'opacity=".35"')).join('') + path('M160 100 Q200 50 240 100 L230 125 L170 125Z', '#bfe3f7', 'stroke="#7fa6bd" opacity="0"'),
  tarp: a => path('M60 110 L340 90 L350 290 L70 320Z', `url(#${a})`, 'stroke="#000" stroke-opacity=".25"') + path('M120 105 L135 310 M200 100 L215 315 M280 95 L290 300', 'none', 'stroke="#000" stroke-width="2" opacity=".15"') + [[70, 120], [340, 100], [345, 285], [78, 310]].map(([x, y]) => circ(x, y, 6, 'url(#steel)')).join(''),
