// SRC colors used by the fallback
const SRC_COLOR = { own: 'yellow', rent: 'orange', ppe: 'orange', supply: 'blue' };
function box(a) { return M.box(a); }
function bottle(a) { return M.bottle(a); }

function motifFor(tool) {
  for (const [re, name, accent] of RULES) if (re.test(tool.name)) return [name, accent || SRC_COLOR[tool.src] || 'yellow'];
  return ['generic', SRC_COLOR[tool.src] || 'blue'];
}

// Extra small-scale detail drawn over the base motif: fasteners, knurling, labels, scale markings, vents, brand plates.
const rivet = (x, y, r = 3) => circ(x, y, r, 'url(#steel)', 'stroke="#000" stroke-opacity=".45" stroke-width=".8"') + circ(x - r * 0.3, y - r * 0.3, r * 0.35, '#fff', 'opacity=".7"');
