const knurl = (x, y, w, h) => Array.from({ length: Math.floor(w / 5) }, (_, i) => line(x + 3 + i * 5, y + 2, x + 3 + i * 5, y + h - 2, '#000', 1, 'opacity=".28"')).join('');
const brand = (x, y, text, color = '#fff', size = 11) => `<text x="${x}" y="${y}" font-family="Arial Black,Arial,sans-serif" font-weight="900" font-size="${size}" letter-spacing="1" fill="${color}" opacity=".9">${esc(text)}</text>`;
