for (const [name, extra] of Object.entries(DETAIL)) { const base = M[name]; M[name] = a => base(a) + extra(a); }

function toolArt(tool) {
  const [name, accent] = motifFor(tool);
  const group = (M[name] || M.generic)(accent);
  const title = esc(tool.name);
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400" width="800" height="800" role="img" aria-label="${title}"><title>${title}</title>${DEFS}<rect width="400" height="400" fill="url(#bg)"/><rect y="318" width="400" height="82" fill="url(#floor)"/><rect y="317" width="400" height="2" fill="#fff" opacity=".7"/>${shadow()}<g filter="url(#grain)">${group}</g></svg>`;
}

module.exports = { toolArt, motifFor };
